node -e '
const intake = require("./src/orderIntake.js");
const ledger = require("./src/billing/ledger.js");
const userService = require("./src/userService.js");
const format = require("./src/quiet/format.js");

const order = { sku: "SKU-1" };
const pricing = { priceCents: 1000, taxCode: "standard" };
const a = intake.fromCart(order, pricing);
const b = intake.fromApi(order, { priceCents: 1000, taxCode: "exempt" });
const c = intake.fromCli(order, { priceCents: 500, taxCode: "standard" });
const d = intake.intake(order, { priceCents: 200, taxCode: "standard" });
console.log(JSON.stringify({ a, b, c, d, balance: ledger.balance(), reverse: ledger.reverse("1"), reverseMissing: ledger.reverse("missing"), user: userService.getUser("u1"), format: format("  x  ") }, null, 2));
'
